  florida: { qEn: 'How long is Florida\'s statute of limitations for written contracts?', qEs: '¿Cuánto dura el plazo de prescripción de Florida para contratos escritos?', aEn: '5 years under Fla. Stat. §95.11(2)(b) — longer than the 4-year window used in many other states.', aEs: '5 años bajo el Estatuto §95.11(2)(b) — más largo que el plazo de 4 años usado en muchos otros estados.' },
  'new-york': { qEn: 'What is New York\'s statute of limitations for a service agreement?', qEs: '¿Cuál es el plazo de prescripción de Nueva York para un acuerdo de servicio?', aEn: '6 years for a written contract under N.Y. C.P.L.R. §213 — one of the longer windows in the country.', aEs: '6 años para un contrato escrito bajo el C.P.L.R. §213 — uno de los plazos más largos del país.' },
  illinois: { qEn: 'Why does Illinois have such a long statute of limitations for contracts?', qEs: '¿Por qué tiene Illinois un plazo de prescripción tan largo para contratos?', aEn: 'Illinois sets a 10-year statute of limitations for written contracts (735 ILCS 5/13-206) — notably longer than most states, meaning a signed agreement stays enforceable for a long time.', aEs: 'Illinois establece un plazo de prescripción de 10 años para contratos escritos (735 ILCS 5/13-206) — notablemente más largo que la mayoría de los estados, lo que significa que un acuerdo firmado sigue siendo exigible por mucho tiempo.' },
  pennsylvania: { qEn: 'What is the statute of limitations for a Pennsylvania service agreement?', qEs: '¿Cuál es el plazo de prescripción para un acuerdo de servicio de Pensilvania?', aEn: '4 years under 42 Pa. C.S. §5525, counted from the date of the breach.', aEs: '4 años bajo 42 Pa. C.S. §5525, contado desde la fecha del incumplimiento.' },
  ohio: { qEn: 'How long is Ohio\'s statute of limitations for written contracts?', qEs: '¿Cuánto dura el plazo de prescripción de Ohio para contratos escritos?', aEn: '8 years under Ohio Rev. Code §2305.06 — shortened from 15 years in a 2021 legal reform, so older cases may still fall under the previous rule.', aEs: '8 años bajo el Código Revisado §2305.06 — acortado de 15 años en una reforma legal de 2021, así que casos más antiguos podrían caer bajo la regla anterior.' },
  georgia: { qEn: 'What is the statute of limitations for a Georgia service agreement?', qEs: '¿Cuál es el plazo de prescripción para un acuerdo de servicio de Georgia?', aEn: '6 years under O.C.G.A. §9-3-24, counted from the date of the breach.', aEs: '6 años bajo O.C.G.A. §9-3-24, contado desde la fecha del incumplimiento.' },
  'north-carolina': { qEn: 'Why is North Carolina\'s statute of limitations for contracts so short?', qEs: '¿Por qué es tan corto el plazo de prescripción de Carolina del Norte para contratos?', aEn: 'North Carolina sets a 3-year window under N.C. Gen. Stat. §1-52 — notably shorter than most states, which means a claim needs to be pursued relatively quickly after a breach.', aEs: 'Carolina del Norte fija un plazo de 3 años bajo el Estatuto §1-52 — notablemente más corto que en la mayoría de los estados, lo que significa que un reclamo debe presentarse relativamente pronto después de un incumplimiento.' },
  michigan: { qEn: 'What is the statute of limitations for a Michigan service agreement?', qEs: '¿Cuál es el plazo de prescripción para un acuerdo de servicio de Míchigan?', aEn: '6 years under MCL §600.5807, counted from the date of the breach.', aEs: '6 años bajo MCL §600.5807, contado desde la fecha del incumplimiento.' },
  'new-jersey': { qEn: 'How long can someone sue over a breached New Jersey service agreement?', qEs: '¿Cuánto tiempo puede alguien demandar por incumplimiento de un acuerdo de servicio de Nueva Jersey?', aEn: '6 years under N.J.S.A. 2A:14-1, counted from the date of the breach.', aEs: '6 años bajo N.J.S.A. 2A:14-1, contado desde la fecha del incumplimiento.' },
  virginia: { qEn: 'What is Virginia\'s statute of limitations for written contracts?', qEs: '¿Cuál es el plazo de prescripción de Virginia para contratos escritos?', aEn: '5 years under Va. Code §8.01-246, counted from the date of the breach.', aEs: '5 años bajo el Código §8.01-246, contado desde la fecha del incumplimiento.' },
  washington: { qEn: 'What is Washington\'s statute of limitations for a service agreement?', qEs: '¿Cuál es el plazo de prescripción de Washington para un acuerdo de servicio?', aEn: '6 years for a written contract under RCW 4.16.040, counted from the date of the breach.', aEs: '6 años para un contrato escrito bajo RCW 4.16.040, contado desde la fecha del incumplimiento.' },
  arizona: { qEn: 'How long can someone sue over a breached Arizona service agreement?', qEs: '¿Cuánto tiempo puede alguien demandar por incumplimiento de un acuerdo de servicio de Arizona?', aEn: '6 years under A.R.S. §12-548, counted from the date of the breach.', aEs: '6 años bajo A.R.S. §12-548, contado desde la fecha del incumplimiento.' },
  massachusetts: { qEn: 'What is Massachusetts\' statute of limitations for a written contract?', qEs: '¿Cuál es el plazo de prescripción de Massachusetts para un contrato escrito?', aEn: '6 years under M.G.L. c.260 §2, counted from the date of the breach.', aEs: '6 años bajo M.G.L. c.260 §2, contado desde la fecha del incumplimiento.' },
  tennessee: { qEn: 'How long is Tennessee\'s statute of limitations for written contracts?', qEs: '¿Cuánto dura el plazo de prescripción de Tennessee para contratos escritos?', aEn: '6 years under T.C.A. §28-3-109, counted from the date of the breach.', aEs: '6 años bajo T.C.A. §28-3-109, contado desde la fecha del incumplimiento.' },
  indiana: { qEn: 'Why is Indiana\'s statute of limitations for contracts so long?', qEs: '¿Por qué es tan largo el plazo de prescripción de Indiana para contratos?', aEn: 'Indiana allows 10 years for written contracts (Ind. Code §34-11-2-11) — notably longer than most states, meaning a signed service agreement stays enforceable for a long time.', aEs: 'Indiana permite 10 años para contratos escritos (Ind. Code §34-11-2-11) — notablemente más largo que la mayoría de los estados, lo que significa que un acuerdo de servicio firmado sigue siendo exigible por mucho tiempo.' },
  missouri: { qEn: 'How long is Missouri\'s statute of limitations for written contracts?', qEs: '¿Cuánto dura el plazo de prescripción de Misuri para contratos escritos?', aEn: '10 years under Mo. Rev. Stat. §516.110 — longer than the 4-to-6-year window used in many other states.', aEs: '10 años bajo Mo. Rev. Stat. §516.110 — más largo que el plazo de 4 a 6 años usado en muchos otros estados.' },
  maryland: { qEn: 'Why is Maryland\'s statute of limitations for contracts so short?', qEs: '¿Por qué es tan corto el plazo de prescripción de Maryland para contratos?', aEn: 'Maryland sets a 3-year window under Cts. & Jud. Proc. §5-101 — notably shorter than most states, so a breach claim needs to be pursued relatively quickly.', aEs: 'Maryland fija un plazo de 3 años bajo Cts. & Jud. Proc. §5-101 — notablemente más corto que la mayoría de los estados, así que un reclamo por incumplimiento debe presentarse relativamente pronto.' },
  wisconsin: { qEn: 'What is Wisconsin\'s statute of limitations for a service agreement?', qEs: '¿Cuál es el plazo de prescripción de Wisconsin para un acuerdo de servicio?', aEn: '6 years under Wis. Stat. §893.43, counted from the date of the breach.', aEs: '6 años bajo Wis. Stat. §893.43, contado desde la fecha del incumplimiento.' },
  colorado: { qEn: 'Why is Colorado\'s statute of limitations for contracts so short?', qEs: '¿Por qué es tan corto el plazo de prescripción de Colorado para contratos?', aEn: 'Colorado sets a 3-year window under C.R.S. §13-80-101 — notably shorter than many states, so a breach claim needs to be pursued relatively quickly after the breach.', aEs: 'Colorado fija un plazo de 3 años bajo C.R.S. §13-80-101 — notablemente más corto que muchos estados, así que un reclamo por incumplimiento debe presentarse relativamente pronto después del incumplimiento.' },
