const NOTE_FAQ: Record<string, { qEn: string; qEs: string; aEn: string; aEs: string }> = {
  california: { qEn: 'What is the maximum interest rate on a California promissory note?', qEs: '¿Cuál es la tasa de interés máxima en un pagaré de California?', aEn: 'Generally 10% per year for non-exempt personal loans under the state constitution\'s usury cap, though many licensed lenders and business loans are exempt — check which category your loan falls into.', aEs: 'Generalmente 10% anual para préstamos personales no exentos bajo el límite de usura de la constitución estatal, aunque muchos prestamistas licenciados y préstamos comerciales están exentos — verifica en qué categoría cae tu préstamo.' },
  texas: { qEn: 'What happens if a Texas promissory note doesn\'t state an interest rate?', qEs: '¿Qué pasa si un pagaré de Texas no indica una tasa de interés?', aEn: 'Without a signed rate agreement, Texas defaults to a low statutory rate (around 6%). A written agreement is required to charge the higher rates generally allowed for the loan type.', aEs: 'Sin un acuerdo de tasa firmado, Texas usa por defecto una tasa legal baja (alrededor de 6%). Se requiere un acuerdo escrito para cobrar las tasas más altas generalmente permitidas para el tipo de préstamo.' },
  florida: { qEn: 'What interest rate triggers criminal usury in Florida?', qEs: '¿Qué tasa de interés activa usura penal en Florida?', aEn: 'Rates of 25% or more can trigger criminal usury penalties under Fla. Stat. §687.03. The civil usury cap for loans under $500,000 is 18%.', aEs: 'Tasas de 25% o más pueden activar sanciones penales por usura bajo el Estatuto §687.03. El límite de usura civil para préstamos menores a $500,000 es 18%.' },
  'new-york': { qEn: 'What is New York\'s usury cap for a promissory note?', qEs: '¿Cuál es el límite de usura de Nueva York para un pagaré?', aEn: 'The civil usury cap is 16% per year; rates at or above 25% can trigger criminal usury charges. Corporate borrowers are generally exempt from these caps.', aEs: 'El límite de usura civil es 16% anual; tasas iguales o superiores a 25% pueden generar cargos penales por usura. Los prestatarios corporativos generalmente están exentos de estos límites.' },
  illinois: { qEn: 'Does a written agreement change the usury cap in Illinois?', qEs: '¿Cambia un acuerdo escrito el límite de usura en Illinois?', aEn: 'Yes. Without one, the cap is 9% per year. A properly documented written agreement removes the cap for many loan types under the Illinois Interest Act — which is why a clear, signed note matters so much here.', aEs: 'Sí. Sin uno, el límite es 9% anual. Un acuerdo escrito debidamente documentado elimina el límite para muchos tipos de préstamo bajo la Ley de Interés de Illinois — por eso un pagaré claro y firmado importa tanto aquí.' },
  pennsylvania: { qEn: 'What is Pennsylvania\'s default interest rate cap?', qEs: '¿Cuál es el límite de tasa de interés predeterminado de Pensilvania?', aEn: '6% without a specific written rate agreement. The Loan Interest and Protection Law allows higher rates when the terms are properly documented in writing.', aEs: '6% sin un acuerdo de tasa escrito específico. La Ley de Interés y Protección de Préstamos permite tasas más altas cuando los términos están debidamente documentados por escrito.' },
  ohio: { qEn: 'What is Ohio\'s default usury cap for a promissory note?', qEs: '¿Cuál es el límite de usura predeterminado de Ohio para un pagaré?', aEn: '8% without a written rate agreement. A written agreement allows up to 25% for many loan types under Ohio Rev. Code §1343.01 — the written note is what unlocks the higher rate.', aEs: '8% sin un acuerdo de tasa escrito. Un acuerdo escrito permite hasta 25% para muchos tipos de préstamo bajo el Código Revisado §1343.01 — el pagaré escrito es lo que habilita la tasa más alta.' },
  georgia: { qEn: 'What is the maximum interest rate on a Georgia promissory note?', qEs: '¿Cuál es la tasa de interés máxima en un pagaré de Georgia?', aEn: '16% for loans under $3,000 without a special lending license (O.C.G.A. §7-4-2); licensed lenders and larger loans follow separate rules, and rates far above the cap can trigger criminal usury.', aEs: '16% para préstamos menores a $3,000 sin una licencia especial de préstamo (O.C.G.A. §7-4-2); los prestamistas con licencia y préstamos mayores siguen reglas separadas, y tasas muy por encima del límite pueden generar usura penal.' },
  'north-carolina': { qEn: 'Does a written agreement change the usury cap in North Carolina?', qEs: '¿Cambia un acuerdo escrito el límite de usura en Carolina del Norte?', aEn: 'Yes. Without one, the cap is 8% per year. A written agreement allows up to 16% for many consumer loans under N.C. Gen. Stat. §24-1.1.', aEs: 'Sí. Sin uno, el límite es 8% anual. Un acuerdo escrito permite hasta 16% para muchos préstamos al consumidor bajo el Estatuto §24-1.1.' },
  michigan: { qEn: 'What happens if a Michigan promissory note doesn\'t specify an interest rate in writing?', qEs: '¿Qué pasa si un pagaré de Míchigan no especifica una tasa de interés por escrito?', aEn: 'Michigan defaults to a low 7% statutory rate. A written rate agreement is required to charge up to the 25% generally allowed for most loan types (MCL §438.31).', aEs: 'Míchigan usa por defecto una tasa legal baja del 7%. Se requiere un acuerdo de tasa escrito para cobrar hasta el 25% generalmente permitido para la mayoría de los tipos de préstamo (MCL §438.31).' },
  'new-jersey': { qEn: 'Does the usury cap differ for individuals vs. businesses in New Jersey?', qEs: '¿El límite de usura difiere entre individuos y empresas en Nueva Jersey?', aEn: 'Yes — 16% for individual borrowers and 30% for corporate borrowers (N.J.S.A. 31:1-1). Rates of 50% or more can trigger criminal usury charges regardless of borrower type.', aEs: 'Sí — 16% para prestatarios individuales y 30% para prestatarios corporativos (N.J.S.A. 31:1-1). Tasas de 50% o más pueden generar cargos penales por usura sin importar el tipo de prestatario.' },
  virginia: { qEn: 'What is Virginia\'s general usury cap for a promissory note?', qEs: '¿Cuál es el límite de usura general de Virginia para un pagaré?', aEn: '12% without an applicable exemption (Va. Code §6.2-303). Many common loan categories — business loans and licensed-lender loans among them — are allowed higher rates under separate exemptions.', aEs: '12% sin una exención aplicable (Código §6.2-303). A muchas categorías de préstamo comunes — entre ellas préstamos comerciales y de prestamistas con licencia — se les permiten tasas más altas bajo exenciones separadas.' },
  washington: { qEn: 'What is the maximum interest rate on a Washington promissory note?', qEs: '¿Cuál es la tasa de interés máxima en un pagaré de Washington?', aEn: 'Without a written rate agreement, the greater of 12% or 4 points above the 26-week Treasury bill rate (RCW 19.52.020). A written agreement can set a higher rate for many loan types.', aEs: 'Sin un acuerdo de tasa escrito, el mayor entre 12% o 4 puntos sobre la tasa de las letras del Tesoro a 26 semanas (RCW 19.52.020). Un acuerdo escrito puede fijar una tasa más alta para muchos tipos de préstamo.' },
  arizona: { qEn: 'What happens if an Arizona promissory note doesn\'t state an interest rate?', qEs: '¿Qué pasa si un pagaré de Arizona no indica una tasa de interés?', aEn: 'It defaults to 10% per year. Arizona otherwise lets parties set any rate by written agreement, with no general usury ceiling like some other states.', aEs: 'Se aplica por defecto 10% anual. Arizona por lo demás permite a las partes fijar cualquier tasa mediante acuerdo escrito, sin un límite de usura general como en algunos otros estados.' },
  massachusetts: { qEn: 'What interest rate triggers criminal usury in Massachusetts?', qEs: '¿Qué tasa de interés activa usura penal en Massachusetts?', aEn: '20% or higher under M.G.L. c.271 §49. Business loans and loans to corporations are commonly exempt from the general usury restrictions.', aEs: '20% o más bajo M.G.L. c.271 §49. Los préstamos comerciales y los préstamos a corporaciones suelen estar exentos de las restricciones generales de usura.' },
  tennessee: { qEn: 'How is the maximum interest rate determined for a Tennessee promissory note?', qEs: '¿Cómo se determina la tasa de interés máxima para un pagaré de Tennessee?', aEn: 'By a formula rate published periodically by the Tennessee Department of Financial Institutions (T.C.A. §47-14-103), rather than a single fixed cap — always check the current published rate before setting terms.', aEs: 'Mediante una tasa de fórmula publicada periódicamente por el Departamento de Instituciones Financieras de Tennessee (T.C.A. §47-14-103), en vez de un límite fijo único — siempre revisa la tasa publicada actual antes de fijar los términos.' },
  indiana: { qEn: 'Does a written agreement change the usury cap in Indiana?', qEs: '¿Cambia un acuerdo escrito el límite de usura en Indiana?', aEn: 'Yes. Without one, the cap is 8% per year. A written rate agreement allows higher rates for many loan types under the Indiana Uniform Consumer Credit Code.', aEs: 'Sí. Sin uno, el límite es 8% anual. Un acuerdo de tasa escrito permite tasas más altas para muchos tipos de préstamo bajo el Código Uniforme de Crédito al Consumidor de Indiana.' },
  missouri: { qEn: 'What is Missouri\'s default usury cap for a promissory note?', qEs: '¿Cuál es el límite de usura predeterminado de Misuri para un pagaré?', aEn: '10% without a written rate agreement (Mo. Rev. Stat. §408.020). A written agreement removes the cap for many loan types — the note itself is what unlocks the higher rate.', aEs: '10% sin un acuerdo de tasa escrito (Mo. Rev. Stat. §408.020). Un acuerdo escrito elimina el límite para muchos tipos de préstamo — el pagaré en sí es lo que habilita la tasa más alta.' },
  maryland: { qEn: 'What is Maryland\'s default interest rate cap for a promissory note?', qEs: '¿Cuál es el límite de tasa de interés predeterminado de Maryland para un pagaré?', aEn: '6% without a specific written rate agreement. A written agreement allows up to 24% for many loan types under Md. Code, Com. Law §12-103.', aEs: '6% sin un acuerdo de tasa escrito específico. Un acuerdo escrito permite hasta 24% para muchos tipos de préstamo bajo Md. Code, Com. Law §12-103.' },
  wisconsin: { qEn: 'What is Wisconsin\'s default usury cap for a promissory note?', qEs: '¿Cuál es el límite de usura predeterminado de Wisconsin para un pagaré?', aEn: '5% without a written rate agreement (Wis. Stat. §138.04). A written agreement allows higher rates for most loan types — the written note is what unlocks it.', aEs: '5% sin un acuerdo de tasa escrito (Wis. Stat. §138.04). Un acuerdo escrito permite tasas más altas para la mayoría de los tipos de préstamo — el pagaré escrito es lo que lo habilita.' },
  colorado: { qEn: 'Does a written agreement change the usury cap in Colorado?', qEs: '¿Cambia un acuerdo escrito el límite de usura en Colorado?', aEn: 'Yes. Without one, the cap is 8% per year (C.R.S. §5-12-101). A separate written-agreement statute (C.R.S. §5-13-103) allows higher rates for many loan categories.', aEs: 'Sí. Sin uno, el límite es 8% anual (C.R.S. §5-12-101). Una ley separada de acuerdo escrito (C.R.S. §5-13-103) permite tasas más altas para muchas categorías de préstamo.' },
  minnesota: { qEn: 'What is Minnesota\'s default usury cap for a promissory note?', qEs: '¿Cuál es el límite de usura predeterminado de Minesota para un pagaré?', aEn: '8% without a written rate agreement (Minn. Stat. §334.01). A written agreement allows up to 21.75% for many loan types.', aEs: '8% sin un acuerdo de tasa escrito (Minn. Stat. §334.01). Un acuerdo escrito permite hasta 21.75% para muchos tipos de préstamo.' },
  'south-carolina': { qEn: 'What is South Carolina\'s default legal rate of interest for a promissory note?', qEs: '¿Cuál es la tasa de interés legal predeterminada de Carolina del Sur para un pagaré?', aEn: '8.75% per year when the note doesn\'t specify a rate (S.C. Code §34-31-20). Always state the agreed rate in writing rather than relying on this default.', aEs: '8.75% anual cuando el pagaré no especifica una tasa (S.C. Code §34-31-20). Siempre indica la tasa acordada por escrito en vez de depender de este valor predeterminado.' },
  alabama: { qEn: 'What is Alabama\'s usury cap for a promissory note?', qEs: '¿Cuál es el límite de usura de Alabama para un pagaré?', aEn: '6% without a written contract, or up to 8% with one (Ala. Code §8-8-1) — but loans of $2,000 or more in principal are exempt from the usury limit entirely (Ala. Code §8-8-5).', aEs: '6% sin contrato escrito, o hasta 8% con uno (Ala. Code §8-8-1) — pero los préstamos de $2,000 o más de principal están completamente exentos del límite de usura (Ala. Code §8-8-5).' },
};

const VEHICLE_FAQ: Record<string, { qEn: string; qEs: string; aEn: string; aEs: string }> = {
  california: { qEn: 'Does California require a bill of sale to register a vehicle?', qEs: '¿California exige un contrato de compraventa para registrar un vehículo?', aEn: 'Not for most private-party sales, but the DMV recommends form REG 135 as proof of the sale price and date, and a smog certification is generally required before registration.', aEs: 'No para la mayoría de las ventas entre particulares, pero el DMV recomienda el formulario REG 135 como prueba del precio y fecha de venta, y generalmente se requiere un certificado de emisiones antes del registro.' },
  texas: { qEn: 'What do I need besides a bill of sale to transfer a vehicle title in Texas?', qEs: '¿Qué necesito además de un contrato de compraventa para transferir el título de un vehículo en Texas?', aEn: 'Form 130-U (Application for Texas Title), filed at the county tax office within 30 days of purchase. Sales tax is calculated on the price stated in the bill of sale.', aEs: 'El Formulario 130-U (Solicitud de Título de Texas), presentado en la oficina de impuestos del condado dentro de 30 días de la compra. El impuesto sobre ventas se calcula sobre el precio indicado en el contrato de compraventa.' },
  florida: { qEn: 'Is a bill of sale required to sell a car in Florida?', qEs: '¿Se requiere un contrato de compraventa para vender un auto en Florida?', aEn: 'Yes — Florida requires a bill of sale (HSMV form 82050) for most private vehicle sales, and notarization is recommended to prove the purchase price.', aEs: 'Sí — Florida requiere un contrato de compraventa (formulario HSMV 82050) para la mayoría de las ventas privadas de vehículos, y se recomienda notarización para probar el precio de compra.' },
  'new-york': { qEn: 'When does New York require a bill of sale for a vehicle sale?', qEs: '¿Cuándo exige Nueva York un contrato de compraventa para la venta de un vehículo?', aEn: 'Specifically when the sale price looks below market value or the vehicle is a gift — the DMV uses Form DTF-802 to verify sales tax owed at registration.', aEs: 'Específicamente cuando el precio de venta parece estar por debajo del valor de mercado o el vehículo es un regalo — el DMV usa el Formulario DTF-802 para verificar el impuesto sobre ventas adeudado al registrar el vehículo.' },
  illinois: { qEn: 'How long do I have to transfer a vehicle title after buying in Illinois?', qEs: '¿Cuánto tiempo tengo para transferir el título de un vehículo después de comprarlo en Illinois?', aEn: '20 days from the purchase date, or a delinquent transfer fee applies. A bill of sale isn\'t mandated by the Secretary of State but is strongly recommended as proof of the transaction.', aEs: '20 días desde la fecha de compra, o aplica una tarifa por retraso. El Secretario de Estado no exige un contrato de compraventa, pero se recomienda firmemente como prueba de la transacción.' },
  pennsylvania: { qEn: 'Does Pennsylvania require a separate bill of sale?', qEs: '¿Pensilvania exige un contrato de compraventa separado?', aEn: 'Not if the title is properly assigned at sale, but PennDOT recommends one when the vehicle is a gift or sold below fair market value, for sales tax verification purposes.', aEs: 'No si el título está debidamente cedido al momento de la venta, pero PennDOT recomienda uno cuando el vehículo es un regalo o se vende por debajo del valor justo de mercado, para fines de verificación del impuesto sobre ventas.' },
  ohio: { qEn: 'Does Ohio require a bill of sale for a private vehicle sale?', qEs: '¿Exige Ohio un contrato de compraventa para una venta privada de vehículo?', aEn: 'Either a bill of sale or a properly assigned title is required by the Ohio BMV, and sales tax is collected at the time of title transfer based on the stated price.', aEs: 'El BMV de Ohio exige un contrato de compraventa o un título debidamente cedido, y el impuesto sobre ventas se cobra al momento de la transferencia del título según el precio indicado.' },
  georgia: { qEn: 'What tax applies to a vehicle bill of sale in Georgia?', qEs: '¿Qué impuesto aplica a un contrato de compraventa de vehículo en Georgia?', aEn: 'The Title Ad Valorem Tax (TAVT), a one-time tax paid at title transfer instead of ongoing annual ad valorem tax. It\'s calculated on the vehicle\'s fair market value or the price in the bill of sale, whichever applies.', aEs: 'El Impuesto Ad Valorem del Título (TAVT), un impuesto único pagado al transferir el título en vez de un impuesto ad valorem anual continuo. Se calcula sobre el valor justo de mercado del vehículo o el precio en el contrato de compraventa, según aplique.' },
  'north-carolina': { qEn: 'What tax applies when I buy a car in North Carolina?', qEs: '¿Qué impuesto aplica cuando compro un auto en Carolina del Norte?', aEn: 'A 3% Highway Use Tax (HUT), collected at title transfer instead of traditional sales tax, calculated on the price stated in the bill of sale or title assignment.', aEs: 'Un Impuesto de Uso de Carretera (HUT) del 3%, cobrado al transferir el título en vez del impuesto sobre ventas tradicional, calculado sobre el precio indicado en el contrato de compraventa o cesión de título.' },
  michigan: { qEn: 'Does Michigan require a bill of sale for a used car purchase?', qEs: '¿Exige Míchigan un contrato de compraventa para la compra de un auto usado?', aEn: 'When the title alone doesn\'t clearly show the purchase price, yes — the Secretary of State uses it to calculate the 6% use tax owed at registration.', aEs: 'Cuando el título por sí solo no muestra claramente el precio de compra, sí — el Secretario de Estado lo usa para calcular el impuesto de uso del 6% adeudado al registrar.' },
  'new-jersey': { qEn: 'Is a bill of sale required to register a vehicle in New Jersey?', qEs: '¿Se requiere un contrato de compraventa para registrar un vehículo en Nueva Jersey?', aEn: 'When the title doesn\'t clearly show the purchase price, the MVC requires a bill of sale to verify the sales tax (6.625%) owed at registration.', aEs: 'Cuando el título no muestra claramente el precio de compra, la MVC exige un contrato de compraventa para verificar el impuesto sobre ventas (6.625%) adeudado al registrar.' },
  virginia: { qEn: 'What tax applies to a Virginia vehicle bill of sale?', qEs: '¿Qué impuesto aplica a un contrato de compraventa de vehículo en Virginia?', aEn: 'Virginia\'s Sales and Use Tax (SUT), calculated on the price stated in the bill of sale, with a statutory minimum tax that applies even if a very low price is listed.', aEs: 'El Impuesto de Ventas y Uso (SUT) de Virginia, calculado sobre el precio indicado en el contrato de compraventa, con un impuesto mínimo legal que aplica incluso si se indica un precio muy bajo.' },
  washington: { qEn: 'Is a bill of sale required to sell a car in Washington State?', qEs: '¿Se requiere un contrato de compraventa para vender un auto en el estado de Washington?', aEn: 'Not strictly for most private sales, but the Department of Licensing recommends one, and use tax may be assessed on fair market value instead of a stated price that looks too low.', aEs: 'No estrictamente para la mayoría de las ventas privadas, pero el Departamento de Licencias lo recomienda, y el impuesto de uso puede calcularse sobre el valor justo de mercado en vez de un precio indicado que parezca demasiado bajo.' },
  arizona: { qEn: 'What tax applies when I buy a car in Arizona?', qEs: '¿Qué impuesto aplica cuando compro un auto en Arizona?', aEn: 'A transaction privilege tax combining the state rate with county and city rates, calculated on the price stated in the bill of sale and verified by the MVD at registration.', aEs: 'Un impuesto de privilegio de transacción que combina la tasa estatal con tasas de condado y ciudad, calculado sobre el precio indicado en el contrato de compraventa y verificado por la MVD al registrar el vehículo.' },
  massachusetts: { qEn: 'What form does Massachusetts require for a private vehicle sale?', qEs: '¿Qué formulario exige Massachusetts para una venta privada de vehículo?', aEn: 'Form MVU-24 (bill of sale) or a properly assigned title, used by the RMV to verify the 6.25% sales/use tax owed at registration.', aEs: 'El Formulario MVU-24 (contrato de compraventa) o un título debidamente cedido, usado por el RMV para verificar el impuesto de ventas/uso del 6.25% adeudado al registrar.' },
  tennessee: { qEn: 'What do I need to transfer a vehicle title after buying in Tennessee?', qEs: '¿Qué necesito para transferir el título de un vehículo después de comprarlo en Tennessee?', aEn: 'A bill of sale or the assigned title, filed with the county clerk, who calculates the sales tax owed (around 7% state rate plus a local option tax).', aEs: 'Un contrato de compraventa o el título cedido, presentado ante el secretario del condado, quien calcula el impuesto sobre ventas adeudado (alrededor de una tasa estatal de 7% más un impuesto local opcional).' },
  indiana: { qEn: 'Does Indiana require a bill of sale for a used car purchase?', qEs: '¿Exige Indiana un contrato de compraventa para la compra de un auto usado?', aEn: 'The BMV recommends one, especially when the title doesn\'t clearly show the purchase price, since Indiana\'s 7% state sales tax is calculated on that stated price.', aEs: 'El BMV lo recomienda, especialmente cuando el título no muestra claramente el precio de compra, ya que el impuesto sobre ventas estatal del 7% de Indiana se calcula sobre ese precio indicado.' },
  missouri: { qEn: 'Does Missouri require a notarized bill of sale?', qEs: '¿Exige Misuri un contrato de compraventa notariado?', aEn: 'Commonly yes, or the properly assigned title, so the Department of Revenue can calculate the 4.225% state sales tax plus local rates owed at registration.', aEs: 'Comúnmente sí, o el título debidamente cedido, para que el Departamento de Ingresos pueda calcular el impuesto sobre ventas estatal del 4.225% más tasas locales adeudado al registrar.' },
  maryland: { qEn: 'What tax applies to a Maryland vehicle bill of sale?', qEs: '¿Qué impuesto aplica a un contrato de compraventa de vehículo en Maryland?', aEn: 'A 6% excise tax, calculated on the vehicle\'s fair market value or the price in the bill of sale, whichever is higher — the MVA requires the bill of sale when this can\'t be verified from the title alone.', aEs: 'Un impuesto especial del 6%, calculado sobre el valor justo de mercado del vehículo o el precio en el contrato de compraventa, el que sea mayor — la MVA exige el contrato de compraventa cuando esto no puede verificarse solo con el título.' },
  wisconsin: { qEn: 'Is a bill of sale required to register a vehicle in Wisconsin?', qEs: '¿Se requiere un contrato de compraventa para registrar un vehículo en Wisconsin?', aEn: 'The DMV recommends form MV2459 for private sales, especially when the title doesn\'t clearly show the price, since Wisconsin\'s 5% state sales tax is calculated on that figure.', aEs: 'El DMV recomienda el formulario MV2459 para ventas privadas, especialmente cuando el título no muestra claramente el precio, ya que el impuesto sobre ventas estatal del 5% de Wisconsin se calcula sobre esa cifra.' },
  colorado: { qEn: 'What tax applies when I buy a car in Colorado?', qEs: '¿Qué impuesto aplica cuando compro un auto en Colorado?', aEn: 'A 2.9% state sales tax plus local rates, calculated on the price stated in the bill of sale or dealer invoice required by the DMV.', aEs: 'Un impuesto sobre ventas estatal del 2.9% más tasas locales, calculado sobre el precio indicado en el contrato de compraventa o factura del concesionario exigido por el DMV.' },
  minnesota: { qEn: 'When does Minnesota require a bill of sale for a vehicle sale?', qEs: '¿Cuándo exige Minesota un contrato de compraventa para la venta de un vehículo?', aEn: 'For gifts, or when the title doesn\'t clearly show the purchase price — Driver and Vehicle Services uses it to verify the 6.5% Motor Vehicle Sales Tax owed.', aEs: 'Para regalos, o cuando el título no muestra claramente el precio de compra — Servicios de Conductores y Vehículos lo usa para verificar el Impuesto de Ventas de Vehículos Motorizados del 6.5% adeudado.' },
  'south-carolina': { qEn: 'Does South Carolina require a notarized bill of sale for a vehicle?', qEs: '¿Exige Carolina del Sur un contrato de compraventa notariado para un vehículo?', aEn: 'No — the SCDMV\'s Form 4031 only requires buyer and seller signatures. It\'s used to calculate the state\'s Infrastructure Maintenance Fee, capped at 5% of the price or $500, whichever is less.', aEs: 'No — el Formulario 4031 del SCDMV solo requiere las firmas del comprador y vendedor. Se usa para calcular la Tarifa de Mantenimiento de Infraestructura del estado, limitada al 5% del precio o $500, lo que sea menor.' },
  alabama: { qEn: 'When does Alabama require a bill of sale for a vehicle sale?', qEs: '¿Cuándo exige Alabama un contrato de compraventa para la venta de un vehículo?', aEn: 'Specifically when no certificate of title is available. When one is required, it must be notarized or signed by two witnesses, and the vehicle must be registered within 20 days of the sale.', aEs: 'Específicamente cuando no hay un certificado de título disponible. Cuando se requiere uno, debe estar notariado o firmado por dos testigos, y el vehículo debe registrarse dentro de 20 días de la venta.' },
};

